package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;

/** A claim's figure: the due fixed when settled, else the figure its person's last statement bound it
 *  to, else its live due: its amount at the grade rate in force on its date, rounded half to even, and
 *  at least the sheet's floor, except a correction's, which has no floor (null, n/a, when no rate applies). */
public final class ClaimFigure {
    private ClaimFigure() {
    }

    /** amount × pct ÷ 100, rounded half to even to two decimals; null when there is no rate. */
    public static BigDecimal of(BigDecimal amount, BigDecimal pct) {
        return pct == null ? null : amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN);
    }

    /** The live due: amount at pct, raised to the floor; null when there is no rate. */
    public static BigDecimal of(BigDecimal amount, BigDecimal pct, BigDecimal floor) {
        BigDecimal due = of(amount, pct);
        return due == null || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
    }

    /** The figure the claim has now, given the grade's rate in force on its date and the sheet's floor. */
    public static BigDecimal of(Claim claim, BigDecimal pct, BigDecimal floor) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        if (claim.isStated() && claim.getStatedDue() != null) {
            return claim.getStatedDue();
        }
        return claim.isCorrection() ? of(claim.getAmount(), pct) : of(claim.getAmount(), pct, floor);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;

/** What a sheet's late charge follows: its terms (days after a claim's date it is due by), its late
 *  percent and its today. An overdue claim (OPEN, due-by before today) gains the late percent of its
 *  figure for every full 30 days it is overdue, rounded half to even. The charge is never bound by a
 *  statement; settling freezes it into the settled due. */
public record Lateness(int terms, BigDecimal pct, LocalDate today) {

    /** The days in each step of the late charge. */
    private static final int PERIOD_DAYS = 30;

    public static Lateness of(String sheetId, SettingStore settings, SheetStore sheets) {
        return new Lateness(settings.terms(sheetId), settings.latePct(sheetId), sheets.today(sheetId));
    }

    /** The late charge on a claim whose figure (bound, else floored live) is {@code figure}; none on
     *  a correction. */
    public BigDecimal charge(Claim claim, BigDecimal figure) {
        if (figure == null || claim.getStatus() != ClaimStatus.OPEN || today == null || claim.isCorrection()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
        long periods = overdue <= 0 ? 0 : overdue / PERIOD_DAYS;
        return ClaimFigure.of(figure, pct.multiply(BigDecimal.valueOf(periods)));
    }

    /** The claim's due now: its figure, plus the late charge unless settled (its settled due has it). */
    public BigDecimal due(Claim claim, BigDecimal pct, BigDecimal floor) {
        BigDecimal figure = ClaimFigure.of(claim, pct, floor);
        if (figure == null || claim.getSettledDue() != null) {
            return figure;
        }
        return figure.add(charge(claim, figure));
    }
}
